<template><div class="attendance-pwa"><PwaPageHeader icon="fas fa-file-medical" title="Laporan Izin & Cuti" subtitle="Rekap pengajuan per bulan" /><div class="toolbar"><input v-model="filters.bulan" type="month" class="form-control form-control-sm"><button class="btn btn-primary btn-sm" @click="loadData"><i class="fas fa-search"></i></button><button class="btn btn-outline-success btn-sm" @click="exportFile('excel')">XLSX</button><button class="btn btn-outline-danger btn-sm" @click="exportFile('pdf')">PDF</button></div><div class="summary"><div v-for="c in cards" :key="c.key"><span>{{c.label}}</span><strong>{{summary[c.key]||0}}</strong></div></div><div class="card"><div class="title"><div><h6>Daftar Pengajuan</h6><span>{{monthLabel}}</span></div></div><div v-if="loading" class="empty">Memuat laporan...</div><div v-else-if="!rows.length" class="empty">Tidak ada pengajuan.</div><div v-else class="list"><div v-for="r in rows" :key="`${r.no}-${r.nip}-${r.tanggal_mulai}`" class="item"><div class="top"><div><strong>{{r.nama}}</strong><small>{{r.nip}} · {{r.jabatan||'-'}}</small></div><span class="status" :class="statusClass(r.status)">{{r.status}}</span></div><div class="grid"><div><span>Kategori</span><strong>{{r.kategori}} · {{r.jenis}}</strong></div><div><span>Hari</span><strong>{{r.jumlah_hari}}</strong></div></div><div class="mini"><span>Periode</span><strong>{{r.tanggal_mulai}} s.d {{r.tanggal_selesai}}</strong></div><div class="mini"><span>Kalender dalam periode</span><strong>{{r.nama_kalender_dalam_periode||'Tidak ada hari libur khusus'}} · {{r.hari_libur_dalam_periode||0}} hari libur</strong></div><div class="mini"><span>Keperluan</span><strong>{{r.keperluan||'-'}}</strong></div></div></div></div></div></template>
<script setup>import PwaPageHeader from '../../../components/PwaPageHeader.vue';defineProps({filters:{type:Object,required:true},rows:{type:Array,default:()=>[]},loading:Boolean,exporting:Boolean,summary:{type:Object,default:()=>({})},monthLabel:{type:String,default:''},statusClass:{type:Function,required:true},loadData:{type:Function,required:true},exportFile:{type:Function,required:true}});const cards=[{key:'total',label:'Total'},{key:'cuti',label:'Cuti'},{key:'izin',label:'Izin'},{key:'disetujui',label:'Disetujui'},{key:'menunggu',label:'Menunggu'},{key:'ditolak',label:'Ditolak'}]</script>
<style scoped>.attendance-pwa{padding:2px 0 84px}.toolbar{display:grid;grid-template-columns:1fr auto auto auto;gap:4px;padding:8px;margin-bottom:6px;background:#fff;border:1px solid #e5e7eb;border-radius:14px}.toolbar .form-control{font-size:11.25px}.toolbar .btn{font-size:9.38px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-bottom:7px}.summary>div{padding:7px;border:1px solid #e5e7eb;border-radius:10px;background:#fff}.summary span{display:block;color:#64748b;font-size:8.75px}.summary strong{display:block;margin-top:2px;color:#111827;font-size:18.75px}.card{padding:10px;background:#fff;border:1px solid #e5e7eb;border-radius:15px}.title{margin-bottom:7px}.title h6{margin:0;color:#111827;font-size:15px;font-weight:950}.title span{color:#64748b;font-size:10px}.list{display:flex;flex-direction:column;gap:6px}.item{padding:8px;border:1px solid #eef2f7;border-radius:11px}.top{display:flex;justify-content:space-between;gap:6px}.top strong{display:block;color:#111827;font-size:11.88px}.top small{display:block;color:#64748b;font-size:9px;margin-top:2px}.status{padding:3px 5px;border-radius:999px;background:#f1f5f9;color:#475569;font-size:8.75px;font-weight:900}.status.approved{background:#dcfce7;color:#166534}.status.pending{background:#fef3c7;color:#92400e}.status.rejected{background:#fee2e2;color:#991b1b}.grid{display:grid;grid-template-columns:1fr 52px;gap:6px;margin-top:6px}.grid>div,.mini{padding-top:5px;border-top:1px solid #f1f5f9}.grid span,.mini span{display:block;color:#94a3b8;font-size:8.75px}.grid strong,.mini strong{display:block;margin-top:2px;color:#334155;font-size:10.62px;line-height:1.3}.mini{margin-top:6px}.empty{min-height:120px;display:flex;align-items:center;justify-content:center;color:#64748b;font-size:11.25px}@media(max-width:430px){.toolbar{grid-template-columns:1fr auto}.summary{grid-template-columns:repeat(2,1fr)}}
